import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "xp",
  motion: "reduced",
  sidebarLayout: "sidebar",
  indicators: { sidebar: "none", tree: "none" },
  adornments: {
    "chat-layout": {
      titlebar: (
        <div
          aria-hidden="true"
          className="flex h-[27px] shrink-0 select-none items-center rounded-t-[5px] bg-[image:var(--xp-titlebar)] px-2 font-['Trebuchet_MS',Tahoma,sans-serif] text-[13px] font-bold text-[var(--xp-white)] text-shadow-[1px_1px_var(--xp-title-shadow)]"
        >
          Agent Chat
        </div>
      ),
    },
  },
};

@import "../retro-system-font.css";

@import "./xp-controls.css";

[data-skin="xp"] {
  --xp-white: oklch(1 0 0);
  --xp-face: var(--secondary);
  --xp-light: oklch(1 0 0);
  --xp-shadow: oklch(0.8607 0.0186 78.229);
  --xp-field: oklch(0.6833 0.0533 246.812);
  --xp-edge: oklch(0.3571 0.1109 253.22);
  --xp-button: linear-gradient(oklch(1 0 0), oklch(0.9392 0.0081 98.883) 86%, oklch(0.8607 0.0186 78.229));
  --xp-button-pressed: linear-gradient(
    oklch(0.8394 0.0102 87.48),
    oklch(0.9136 0.0107 106.61) 8%,
    oklch(0.92 0.0094 106.582) 94%,
    oklch(0.9609 0.0013 106.424)
  );
  --xp-hover-rim:
    inset -1px 1px oklch(0.9586 0.046 86.465), inset 1px 2px oklch(0.8966 0.1061 85.255), inset -2px 2px oklch(0.8566 0.1329 82.142), inset 2px -2px oklch(
      0.754 0.1526 76.578
    );
  --xp-default-rim:
    inset -1px 1px oklch(0.9171 0.0423 247.19), inset 1px 2px oklch(0.777 0.08 259.188), inset -2px 2px oklch(0.8632 0.054 257.078), inset 2px -2px oklch(
      0.7419 0.0893 258.691
    );
  --xp-frame-shadow:
    inset -1px -1px oklch(0.3054 0.1896 264.19), inset 1px 1px oklch(0.4393 0.2509 264.572), inset -2px -2px oklch(0.3447 0.2038 264.074), inset 2px 2px oklch(
      0.5593 0.2133 260.155
    ), inset -3px -3px oklch(0.4535 0.2436 263.553), inset 3px 3px oklch(0.5021 0.2181 261.634);
  --xp-titlebar: linear-gradient(
    oklch(0.6652 0.1851 249.79),
    oklch(0.5134 0.2418 262.234) 8%,
    oklch(0.5082 0.2451 262.523) 40%,
    oklch(0.5635 0.2408 260.818) 88%,
    oklch(0.5435 0.2531 262.093) 95%,
    oklch(0.4534 0.2381 263.377) 96%
  );
  --xp-title-shadow: oklch(0.3029 0.185 267.774);
  --xp-close: linear-gradient(
    135deg,
    oklch(0.8223 0.0782 33.584),
    oklch(0.6738 0.1654 37.394) 35%,
    oklch(0.6286 0.2041 36.849) 70%,
    oklch(0.4848 0.1737 34.135)
  );
  --xp-task-pane: linear-gradient(oklch(0.7116 0.1103 261.382), oklch(0.5949 0.1485 273.172));
  --xp-task-heading: linear-gradient(90deg, oklch(1 0 0), oklch(0.8686 0.052 269.632));
  --xp-task-body: oklch(0.9042 0.0343 269.307);
  --xp-link: oklch(0.5032 0.1754 260.787);
  --xp-tab: oklch(0.9916 0.0026 286.352);
  --xp-tab-border: oklch(0.7157 0.0311 233.807);
  --xp-tab-orange: oklch(0.8575 0.1584 85.332);
  --xp-check: oklch(0.619 0.1943 142.776);
  --xp-progress: oklch(0.6725 0.1979 143.721);
  --xp-tooltip: oklch(0.9922 0.039 107.089);
  --xp-scroll: linear-gradient(
    90deg,
    oklch(1 0 0),
    oklch(0.8767 0.0568 267.632) 20%,
    oklch(0.8316 0.0679 264.509) 80%,
    oklch(0.8723 0.0576 265.652)
  );
}

:where(.dark) [data-skin="xp"],
.dark[data-skin="xp"] {
  --xp-light: oklch(0.4 0.014 257);
  --xp-shadow: oklch(0.18 0.005 248);
  --xp-field: var(--input);
  --xp-edge: oklch(0.54 0.05 260);
  --xp-button: linear-gradient(oklch(0.37 0.012 253), var(--secondary) 86%, oklch(0.22 0.01 250));
  --xp-button-pressed: linear-gradient(oklch(0.22 0.01 250), var(--secondary));
  --xp-hover-rim: inset 0 0 0 2px var(--ring);
  --xp-default-rim: inset 0 0 0 2px var(--primary);
  --xp-task-pane: linear-gradient(oklch(0.31 0.07 266), oklch(0.23 0.04 266));
  --xp-task-heading: linear-gradient(90deg, oklch(0.38 0.025 266), oklch(0.3 0.03 266));
  --xp-task-body: oklch(0.28 0.02 266);
  --xp-link: oklch(0.8 0.09 260);
  --xp-tab: var(--background);
  --xp-tab-border: var(--input);
  --xp-check: oklch(0.75 0.17 145);
  --xp-tooltip: oklch(0.31 0.025 95);
  --xp-scroll: linear-gradient(90deg, oklch(0.45 0.04 257), oklch(0.33 0.04 260));
}

@layer components {
  [data-skin="xp"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-radius: 0px;
    --cui-popup-background: var(--popover);
    --cui-popup-foreground: var(--foreground);
    --cui-popup-border-color: var(--xp-field);
    --cui-popup-border-width: 1px;
    --cui-popup-shadow: 2px 2px 2px oklch(0 0 0 / 0.25);
    --cui-popup-backdrop-filter: none;
    --cui-popup-item-radius: 0px;
    --cui-popup-item-highlight-background: var(--primary);
    --cui-popup-item-highlight-foreground: var(--primary-foreground);
    --cui-popup-item-highlight-muted-foreground: var(--primary-foreground);
    --cui-popup-separator-color: var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="popup"][data-popup-part="item"]) {
    min-block-size: 20px;
    padding-block: 2px;
  }
  [data-skin="xp"] :where([data-control-family="popup"][data-popup-part="label"]) {
    text-transform: none;
    letter-spacing: normal;
  }
  [data-skin="xp"] :where([data-control-family="popup"][data-popup-part="bar"]) {
    --cui-popup-background: var(--secondary);
    --cui-popup-shadow: inset 1px 1px var(--xp-light), inset -1px -1px var(--xp-shadow);
  }
  [data-skin="xp"]
    :where([data-control-family="popup"][data-popup-part="surface"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    --cui-popup-radius: 8px 8px 0 0;
    --cui-popup-background: var(--secondary);
    --cui-popup-border-width: 0px;
    --cui-popup-shadow: var(--xp-frame-shadow), 3px 3px 8px oklch(0 0 0 / 0.3);
    padding: 3px;
    gap: 12px;
  }
  [data-skin="xp"]
    :where([data-control-family="popup"][data-slot="header"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    padding: 0;
    gap: 12px;
  }
  [data-skin="xp"]
    :where([data-control-family="popup"][data-slot="title"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    min-block-size: 27px;
    padding: 6px 32px 5px 6px;
    border-radius: 5px 5px 0 0;
    background: var(--xp-titlebar);
    color: var(--xp-white);
    font:
      700 13px / 16px "Trebuchet MS",
      Tahoma,
      sans-serif;
    letter-spacing: normal;
    text-shadow: 1px 1px var(--xp-title-shadow);
  }
  [data-skin="xp"]
    :where([data-control-family="popup"][data-slot="description"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    padding-inline: 12px;
    color: var(--foreground);
  }
  [data-skin="xp"] :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]) {
    opacity: 1;
    --cui-button-background-image: var(--xp-close);
    --cui-button-foreground: var(--xp-white);
    --cui-button-hover-foreground: var(--xp-white);
    --cui-button-shadow: inset 1px 1px 1px oklch(1 0 0 / 0.6), inset -1px -1px 1px oklch(0 0 0 / 0.25);
    --cui-button-hover-shadow: inset 0 0 0 1px var(--xp-white);
    --cui-button-height: 21px;
    --cui-button-icon: 13px;
    border: 1px solid var(--xp-white);
    top: 6px;
    right: 6px;
  }
  [data-skin="xp"] :where([data-control-family="popup"][data-popup-kind="tooltip"][data-popup-part="surface"]) {
    --cui-popup-background: var(--xp-tooltip);
    --cui-popup-border-color: var(--foreground);
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="root"]) {
    --cui-sidebar-inner-background: var(--xp-task-body);
    --cui-sidebar-inner-background-image: none;
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-inner-radius: 0px;
    --cui-sidebar-inner-shadow: none;
    --cui-sidebar-group-label-foreground: var(--xp-link);
    --cui-sidebar-menu-button-radius: 0px;
    --cui-sidebar-menu-button-foreground: var(--xp-link);
    --cui-sidebar-menu-button-hover-background: transparent;
    --cui-sidebar-menu-button-hover-foreground: var(--xp-link);
    --cui-sidebar-menu-button-active-background: var(--primary);
    --cui-sidebar-menu-button-active-foreground: var(--primary-foreground);
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="content-stack"]) {
    gap: 12px;
    padding: 12px;
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="group"]) {
    padding: 0;
    border: 1px solid var(--xp-light);
    border-radius: 3px 3px 0 0;
    background: var(--xp-task-body);
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="group-label"]) {
    min-block-size: 25px;
    padding: 4px 10px;
    border-radius: 2px 2px 0 0;
    background: var(--xp-task-heading);
    font-weight: 700;
    text-transform: none;
    letter-spacing: normal;
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="menu"]) {
    gap: 0;
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="menu-button"]:hover) {
    text-decoration: underline;
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="menu-button"]) {
    min-block-size: 22px;
    height: auto;
    padding-block: 3px;
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="menu"] [data-control-family="sidebar"][data-slot="menu"]) {
    border-inline-start: 1px dotted var(--xp-field);
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="header"], [data-control-family="sidebar"][data-slot="footer"]) {
    background: var(--secondary);
    box-shadow:
      inset 0 1px var(--xp-light),
      inset 0 -1px var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="tree"][data-slot="root"]) {
    --cui-tree-item-trigger-radius: 0px;
    --cui-tree-item-trigger-selected-background: var(--primary);
    --cui-tree-item-trigger-selected-foreground: var(--primary-foreground);
    background: var(--background);
    border: 1px solid var(--xp-field);
    padding: 3px;
  }
  [data-skin="xp"] :where([data-control-family="tree"][data-slot="item-trigger"]) {
    padding-block: 2px;
  }
  [data-skin="xp"] :where([data-control-family="card"][data-slot="root"]) {
    --cui-card-background: var(--secondary);
    --cui-card-radius: 3px;
    --cui-card-border-color: var(--xp-shadow);
    --cui-card-shadow: inset 1px 1px var(--xp-light);
  }
  [data-skin="xp"] :where([data-control-family="table"][data-slot="root"]) {
    --cui-table-background: var(--background);
  }
  [data-skin="xp"] :where([data-control-family="table"][data-slot="head"]) {
    background: var(--secondary);
    box-shadow:
      inset 1px 1px var(--xp-light),
      inset -1px -1px var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="kbd"][data-slot="root"]) {
    --cui-kbd-radius: 2px;
    --cui-kbd-background: var(--secondary);
    --cui-kbd-shadow: inset 1px 1px var(--xp-light), inset -1px -1px var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="chat-layout"][data-control-ui="chat-layout"][data-slot="root"]) {
    --cui-chat-layout-radius: 8px;
    border-end-start-radius: 0;
    border-end-end-radius: 0;
    --cui-chat-layout-border-color: transparent;
    --cui-chat-layout-shadow: var(--xp-frame-shadow);
    border-width: 0;
    padding: 3px;
  }
  [data-skin="xp"] :where([data-control-family="chat-message"][data-slot="root"][data-role="user"]) {
    --cui-chat-message-foreground: var(--foreground);
    --cui-chat-message-radius: 3px;
    --cui-chat-message-corner-radius: 3px;
    --cui-chat-message-background: var(--xp-task-body);
    --cui-chat-message-border-color: var(--xp-field);
    --cui-chat-message-border-width: 1px;
    --cui-chat-message-shadow: inset 0 1px var(--xp-light);
  }
  [data-skin="xp"]
    :where(
      [data-control-family="scroll-area"][data-slot="root"],
      [data-control-family="sidebar"][data-slot="inner"] [data-control-family="scroll-area"][data-slot="root"]
    ) {
    scrollbar-color: auto;
    scrollbar-width: auto;
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"][data-slot="root"]) {
    --cui-scroll-area-thumb-radius: 2px;
    --cui-scroll-area-thumb-background: var(--xp-scroll);
    --cui-scroll-area-corner-background: var(--secondary);
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"][data-slot="scrollbar"]) {
    background: var(--secondary);
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-orientation="vertical"]) {
    inline-size: 16px;
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-orientation="horizontal"]) {
    block-size: 16px;
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"][data-slot="thumb"]) {
    border: 1px solid var(--xp-field);
    box-shadow:
      inset 1px 1px var(--xp-light),
      inset -1px -1px var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"], [data-control-family="sidebar"])::-webkit-scrollbar {
    width: 16px;
    height: 16px;
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"], [data-control-family="sidebar"])::-webkit-scrollbar-track {
    background: var(--secondary);
    box-shadow: inset 1px 0 var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="scroll-area"], [data-control-family="sidebar"])::-webkit-scrollbar-thumb {
    border: 1px solid var(--xp-field);
    border-radius: 2px;
    background: var(--xp-scroll);
  }
  @media (pointer: coarse) {
    [data-skin="xp"]
      :where(
        [data-control-family="button"][data-control="true"],
        [data-control-family="field"][data-control="true"],
        [data-control-family="sidebar"][data-slot="menu-button"],
        [data-control-family="popup"][data-popup-part="item"]
      ) {
      min-block-size: 44px;
    }
    [data-skin="xp"] :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]) {
      top: 3px;
      right: 3px;
      width: 44px;
    }
  }
}

@layer components {
  [data-skin="xp"] :where([data-control-family="chat-message"][data-slot="content"][data-streaming]) {
    @apply progress-sweep;
    --progress-sweep-color: var(--foreground);
    --progress-sweep-fade: 0.8;
  }
}

@layer components {
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="inner"] [data-control-family="scroll-area"][data-slot="root"]) {
    background-image: var(--xp-task-pane);
  }
  [data-skin="xp"] :where([data-control-family="sidebar"][data-slot="menu"]) {
    padding: 6px 8px;
    background: var(--xp-task-body);
  }
}

@layer components {
  @media (pointer: coarse) {
    [data-skin="xp"]
      :where([data-control-family="popup"][data-slot="title"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
      min-block-size: 50px;
      padding-block: 17px;
      padding-inline-end: 52px;
    }
  }
  [data-skin="xp"]
    :where([data-control-family="toolbar"][data-slot="root"][data-variant="inverse"] [data-control-family="button"][data-control="true"]) {
    --cui-button-background: var(--cui-toolbar-item-background);
    --cui-button-background-image: none;
    --cui-button-foreground: var(--cui-toolbar-item-foreground);
    --cui-button-hover-background: var(--cui-toolbar-item-hover-background);
    --cui-button-hover-foreground: var(--cui-toolbar-item-hover-foreground);
    --cui-button-active-background: var(--cui-toolbar-item-active-background);
    --cui-button-active-foreground: var(--cui-toolbar-item-active-foreground);
    --cui-button-active-hover-background: var(--cui-toolbar-item-active-background);
    --cui-button-shadow: var(--cui-toolbar-item-shadow);
  }
}

[data-skin="xp"][data-skin] {
  --font-sans: Tahoma, Arial, sans-serif;
  --font-mono: "Lucida Console", Consolas, monospace;
  --text-body: 0.75rem;
  --text-caption: 0.6875rem;
  --text-body-lg: 0.8125rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.2178 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.2178 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2178 0 0);
  --primary: oklch(0.5354 0.1543 259.46);
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.9501 0.0174 99.605);
  --muted-foreground: oklch(0.47 0.0245 98.401);
  --secondary: oklch(0.9318 0.0228 98.65);
  --secondary-foreground: oklch(0.2178 0 0);
  --accent: oklch(0.5354 0.1543 259.46);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.577 0.1823 25.932);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.6817 0.0116 204.079 / var(--ring-opacity));
  --input: oklch(0.6833 0.0533 246.812);
  --ring: oklch(0.8118 0.1544 77.609);
  --focus-ring: var(--foreground);
  --focus-ring-style: dotted;
  --focus-ring-width: 1px;
  --focus-ring-offset: -4px;
  --canvas: oklch(0.9318 0.0228 98.65);
  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;
  --overlay-opacity: 0.3;
  --backdrop-blur-overlay: 0px;
  --scroll-fade-size: 0rem;
  --shadow-color: oklch(0 0 0);
  --shadow-size: 0.4;
  --shadow-opacity: 1;
  --radius: 0rem;
  --radius-control: calc(var(--radius) * 2);
  --popover-padding: 2px;
  --radius-popup-item: calc(var(--radius-control) * 0.6);
  --padding-x: 0.625rem;
  --padding-y: 0.375rem;
  --control-h: 1.625rem;
  --ease-standard: linear;
  --ease-emphasized: linear;
  --duration-fast: 0ms;
  --duration-base: 0ms;
  --duration-slow: 0ms;
  --text-label: 0.6875rem;
  --radius-field: calc(var(--radius) * 2.2);
  --radius-panel: calc(var(--radius) * 2.6);
  --radius-scene: calc(var(--radius) * 2.8);
}
:where(.dark) [data-skin="xp"][data-skin],
.dark[data-skin="xp"][data-skin] {
  --background: oklch(0.2459 0.0072 248.122);
  --foreground: oklch(0.919 0.0071 88.645);
  --card: oklch(0.2795 0.0085 255.574);
  --card-foreground: oklch(0.919 0.0071 88.645);
  --popover: oklch(0.2795 0.0085 255.574);
  --popover-foreground: oklch(0.919 0.0071 88.645);
  --primary: oklch(0.5512 0.1425 260.917);
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.2958 0.0084 255.567);
  --muted-foreground: oklch(0.7028 0.0111 247.986);
  --secondary: oklch(0.2958 0.0084 255.567);
  --secondary-foreground: oklch(0.919 0.0071 88.645);
  --accent: oklch(0.5016 0.1504 261.426);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.574 0.1623 27.404);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.3847 0.0136 256.762 / var(--ring-opacity));
  --input: oklch(0.4441 0.0229 248.341);
  --ring: oklch(0.7319 0.1299 74.539);
  --canvas: oklch(0.1763 0.0052 248.125);
  --shadow-color: oklch(0 0 0);
}

@layer components {
  [data-skin="xp"]
    :where(
      [data-control-family="button"],
      [data-control-family="field"],
      [data-control-family="choice"],
      [data-control-family="tabs"],
      [data-control-family="sidebar"],
      [data-control-family="tree"],
      [data-control-family="popup"],
      [data-control-family="kbd"]
    ) {
    font-family: "Control UI MS Sans Serif", Tahoma, Arial, sans-serif;
  }
  [data-skin="xp"] :where([data-control-family="button"][data-control="true"]) {
    --cui-button-radius: max(3px, var(--radius-control));
    --cui-button-gap: 4px;
    --cui-button-icon: 13px;
    --cui-button-press-scale: 1;
    --cui-button-foreground: var(--foreground);
    --cui-button-hover-foreground: var(--foreground);
    --cui-button-hover-background: transparent;
    --cui-button-press-background: transparent;
    --cui-button-active-background: var(--secondary);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--secondary);
    --cui-button-shadow: none;
    --cui-button-hover-shadow: inset 1px 1px var(--xp-light), inset -1px -1px var(--xp-shadow);
    --cui-button-press-shadow: inset 1px 1px var(--xp-shadow), inset -1px -1px var(--xp-light);
    --cui-button-active-shadow: var(--cui-button-press-shadow);
    border: 1px solid transparent;
    line-height: 1;
    font-weight: 400;
  }
  [data-skin="xp"] :where([data-control-family="button"][data-control="true"]:is([data-variant="surface"], [data-variant="solid"])) {
    --cui-button-background: var(--secondary);
    --cui-button-background-image: var(--xp-button);
    --cui-button-hover-shadow: var(--xp-hover-rim);
    --cui-button-press-shadow: none;
    border-color: var(--xp-edge);
  }
  [data-skin="xp"] :where([data-control-family="button"][data-control="true"][data-variant="solid"]) {
    --cui-button-shadow: var(--xp-default-rim);
  }
  [data-skin="xp"]
    :where(
      [data-control-family="button"][data-control="true"]:is([data-variant="surface"], [data-variant="solid"]):not([data-icon-only="true"])
    ) {
    min-inline-size: 75px;
  }
  [data-skin="xp"]
    :where(
      [data-control-family="button"][data-control="true"]:is(:active, [data-pressed]):is([data-variant="surface"], [data-variant="solid"])
    ) {
    --cui-button-background-image: var(--xp-button-pressed);
  }
  [data-skin="xp"] :where([data-control-family="button"][data-control="true"][data-tone="danger"]) {
    --cui-button-foreground: var(--destructive-text);
    --cui-button-hover-foreground: var(--destructive-text);
    --cui-button-active-foreground: var(--destructive-text);
  }
  [data-skin="xp"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: 0px;
    --cui-field-background: var(--background);
    --cui-field-foreground: var(--foreground);
    --cui-field-border-color: var(--xp-field);
    --cui-field-border-width: 1px;
    --cui-field-shadow: none;
    --cui-field-padding-inline: 4px;
    --cui-field-focus-border-color: var(--primary);
  }
  [data-skin="xp"] :where([data-control-ui="select"][data-slot="trigger"][data-control-family="button"]) {
    --cui-button-background: var(--background);
    --cui-button-background-image: none;
    --cui-button-hover-background: var(--background);
    --cui-button-press-background: var(--background);
    --cui-button-padding-inline: 4px;
    --cui-button-radius: 0px;
    border-color: var(--xp-field);
  }
  [data-skin="xp"] :where([data-control-ui="select"][data-slot="icon"][data-control-family="popup"]) {
    align-self: stretch;
    width: 17px;
    margin: 1px -2px 1px 4px;
    border: 1px solid var(--xp-field);
    border-radius: 2px;
    background: var(--xp-scroll);
    color: var(--xp-edge);
    rotate: 0deg;
  }
  [data-skin="xp"]
    :where(
      [data-control-family="choice"][data-slot="root"][data-choice-kind="checkbox"],
      [data-control-family="choice"][data-slot="item"][data-choice-kind="radio-group"]
    ) {
    --cui-choice-border-color: var(--xp-field);
    --cui-choice-checked-border-color: var(--xp-field);
    --cui-choice-checked-background: var(--background);
    inline-size: 13px;
    block-size: 13px;
    color: var(--xp-check);
    background-image: linear-gradient(135deg, oklch(from var(--xp-field) l c h / 0.3), transparent 70%);
  }
  [data-skin="xp"] :where([data-control-family="choice"][data-slot="root"][data-choice-kind="checkbox"]) {
    --cui-choice-radius: 0px;
  }
  [data-skin="xp"] :where([data-control-family="choice"][data-slot="indicator"][data-choice-kind="radio-group"]) {
    background: currentColor;
  }
  [data-skin="xp"] :where([data-control-family="switch"][data-slot="root"]) {
    --cui-switch-background: var(--secondary);
    --cui-switch-hover-background: var(--secondary);
    --cui-switch-thumb-radius: 2px;
    --cui-switch-thumb-background: var(--background);
    --cui-switch-thumb-shadow: inset 1px 1px var(--xp-light), inset -1px -1px var(--xp-shadow);
    border-radius: 3px;
    box-shadow: inset 0 0 0 1px var(--xp-field);
  }
  [data-skin="xp"] :where([data-control-family="tabs"][data-slot="root"]) {
    --cui-tabs-trigger-radius: 3px;
    --cui-tabs-list-padding: 0px;
    --cui-tabs-list-background: transparent;
    --cui-tabs-foreground: var(--foreground);
    --cui-tabs-active-foreground: var(--foreground);
    --cui-tabs-indicator-background: transparent;
    --cui-tabs-indicator-shadow: none;
  }
  [data-skin="xp"] :where([data-control-family="tabs"][data-slot="list"]) {
    gap: 0;
    align-items: end;
    border-bottom: 1px solid var(--xp-tab-border);
  }
  [data-skin="xp"] :where([data-control-family="tabs"][data-slot="tab"]) {
    border: 1px solid var(--xp-tab-border);
    border-bottom: 0;
    border-end-start-radius: 0;
    border-end-end-radius: 0;
    background: var(--xp-button);
    margin-bottom: -1px;
    font-weight: 400;
  }
  [data-skin="xp"] :where([data-control-family="tabs"][data-slot="tab"][aria-selected="true"]) {
    background: var(--xp-tab);
    box-shadow: inset 0 2px var(--xp-tab-orange);
    padding-bottom: 2px;
    border-bottom: 1px solid var(--xp-tab);
  }
  [data-skin="xp"] :where([data-control-family="range"][data-slot="root"]) {
    --cui-range-track-radius: 2px;
    --cui-range-track-background: var(--background);
    --cui-range-indicator-radius: 0px;
    --cui-range-indicator-background: var(--xp-progress);
    --cui-range-thumb-radius: 3px;
    --cui-range-thumb-background: var(--secondary);
    --cui-range-thumb-border-color: var(--xp-field);
    --cui-range-thumb-shadow: inset 1px 1px var(--xp-light), inset -1px -1px var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="range"][data-slot="track"]:is([data-range-kind="progress"], [data-range-kind="meter"])) {
    block-size: 16px;
    padding: 2px;
    border: 1px solid var(--xp-field);
  }
  [data-skin="xp"]
    :where([data-control-family="range"][data-slot="indicator"]:is([data-range-kind="progress"], [data-range-kind="meter"])) {
    max-block-size: 100%;
    background-image: linear-gradient(oklch(1 0 0 / 0.4), transparent 45%, oklch(0 0 0 / 0.15));
    mask-image: repeating-linear-gradient(90deg, oklch(0 0 0) 0 6px, transparent 6px 8px);
  }
  [data-skin="xp"] :where([data-control-family="range"][data-range-kind="slider"][data-slot="track"]:not([data-labeled])) {
    block-size: 4px;
    border: 1px solid var(--xp-field);
  }
  [data-skin="xp"] :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"][data-variant="default"]) {
    inline-size: 11px;
    block-size: 21px;
    background-image: var(--xp-button);
    scale: 1;
  }

  [data-skin="xp"] :where([data-control-family="field"][data-field-kind="native-select"][data-slot="icon"]) {
    display: grid;
    place-items: center;
    inset-block: 2px;
    right: 2px;
    inline-size: 17px;
    background: var(--xp-scroll);
    border: 1px solid var(--xp-field);
    border-radius: 2px;
    box-shadow:
      inset 1px 1px var(--xp-light),
      inset -1px -1px var(--xp-shadow);
  }
  [data-skin="xp"] :where([data-control-family="field"][data-field-kind="native-select"][data-slot="root"]) {
    padding-inline-end: 23px;
  }
  [data-skin="xp"]
    :where(
      [data-control-family="field"][data-field-kind="number-field"]:is(
        [data-control-family="field"][data-slot="increment"],
        [data-control-family="field"][data-slot="decrement"]
      )
    ) {
    background: var(--xp-scroll);
    box-shadow:
      inset 1px 1px var(--xp-light),
      inset -1px -1px var(--xp-shadow);
    border: 1px solid var(--xp-field);
    border-radius: 2px;
  }
  [data-skin="xp"]
    :where(
      [data-control-family="field"][data-field-kind="number-field"]:is(
        [data-control-family="field"][data-slot="increment"],
        [data-control-family="field"][data-slot="decrement"]
      ):active
    ) {
    box-shadow: var(--xp-default-rim);
  }
}
